// parseAll lexes and parses input into server blocks, just like Parse, but
// also keeps track of every file-based import that is actually read during
// parsing, in the order in which each file is first read. The raw on-disk
// contents are preserved so callers can lint imported files without having
// to re-expand the imports themselves. Snippet imports, empty files, and
// unmatched glob patterns are not tracked. If the same file is imported
// multiple times, only its first read is recorded.
func parseAll(filename string, input []byte) ([]ServerBlock, []importedFile, error) {
	// unfortunately, we must copy the input because parsing must
	// remain a read-only operation, but we have to expand environment
	// variables before parsing, which changes the underlying array (#4422)
	inputCopy := make([]byte, len(input))
	copy(inputCopy, input)

	tokens, err := allTokens(filename, inputCopy)
	if err != nil {
		return nil, nil, err
	}
	p := parser{
		Dispenser: NewDispenser(tokens),
		importGraph: importGraph{
			nodes: make(map[string]struct{}),
			edges: make(adjacency),
		},
	}
	blocks, err := p.parseAll()
	return blocks, p.importedFiles(), err
}

// importedFile records the original on-disk contents of a file read while
// expanding an import, keyed by its absolute path.
type importedFile struct {
	absPath string
	body    []byte
}

