func TestScratchE2E(t *testing.T) {
	dir := t.TempDir()
	os.WriteFile(filepath.Join(dir, "good.txt"), []byte("respond \"ok\"\n"), 0o644)
	os.WriteFile(filepath.Join(dir, "bad.txt"), []byte("   respond \"ok\"\n"), 0o644)

	a := caddyfile.Adapter{ServerType: ServerType{}}
	root := []byte("localhost:19999 {\n\timport good.txt\n\timport bad.txt\n}\n")
	out, warnings, err := a.Adapt(root, map[string]any{"filename": filepath.Join(dir, "Caddyfile")})
	if err != nil {
		t.Fatal(err)
	}
	var cfg map[string]any
	if err := json.Unmarshal(out, &cfg); err != nil {
		t.Fatalf("invalid JSON: %v: %s", err, out)
	}
	for _, w := range warnings {
		fmt.Printf("WARN: %+v\n", w)
	}
	if len(warnings) != 1 || warnings[0].File != filepath.Join(dir, "bad.txt") {
		t.Fatalf("unexpected warnings: %+v", warnings)
	}
}
EOF
